import hashlib,json,statistics,subprocess,sys
from pathlib import Path
root=Path(__file__).resolve().parents[1];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
meta=json.loads((root/'artifacts/handshake-inline-candidate.json').read_text());servers={'before':root/meta['baseline']['path'],'selected':root/meta['directory']/'war-relay'}
runner=root/meta['driver']['directory']/'scripts/handshake-pressure.py';client=root/meta['helper']['directory']/'admission'
output=root/'docs/benchmarks/2026-10-16-handshake-inline-comparison.json';cohorts=[(w,n,kind) for n,kind in [(0,'drip'),(1024,'idle'),(1024,'drip'),(4096,'drip')] for w in [1,4]]
record={'scope':'48 sequential fresh isolated native processes; three alternating six-second rounds, one/four workers,0/1024/4096 pending HTTP sockets. Incomplete headers receive32 paced bytes with drained TCP receive queues after every round, or stay idle. Setup is paced in batches128 outside the healthy window, at unchanged1024 listen backlog. Frozen independent CBOR client onCPU4 verifies full1KiB cyclic bodies/sender/FIFO and normal Close/EOF during pending input and absolute five-second timeout cleanup. Server CPUs0-3/controller5-7. Every pending socket expires without response bytes;16 renewed slots and exact independent counters prove reservation/admission reuse and final retirement. No builds, profiles, fault injection or competing benchmark load overlaps any ordinary comparison/guard. Failed cases retained without replacement. Server CPU includes raw/recovery work during the actual healthy phase; setup cost is outside that boundary.','candidate':meta,'driver_source':Path(__file__).read_text(),'variants':{k:{'path':str(p.relative_to(root)),'sha256':sha(p)} for k,p in servers.items()},'client':{'path':str(client.relative_to(root)),'sha256':sha(client)},'cases':[],'passed':False}
for repetition in range(1,4):
 for workers,n,kind in cohorts if repetition%2 else reversed(cohorts):
  for role in ['before','selected'] if repetition%2 else ['selected','before']:
   cohort=f'w{workers}-n{n}-{kind}';trace=output.with_name(f'2026-10-16-handshake-inline-{cohort}-{role}-{repetition}.json')
   command=[sys.executable,str(runner),'--server',str(servers[role]),'--client',str(client),'--workers',str(workers),'--connections',str(n),'--kind',kind,'--isolate','--output',str(trace)]
   done=subprocess.run(command,cwd=root,capture_output=True,text=True,timeout=80);data=json.loads(trace.read_text())
   row={'cohort':cohort,'workers':workers,'connections':n,'input':kind,'kind':role,'repetition':repetition,'passed':data['passed'],'exit_code':done.returncode,'trace':str(trace.relative_to(root)),'sha256':sha(trace),'error':data.get('error')}
   if data['passed']:
    assert done.returncode==0 and not data['profile_diagnostic'] and data['isolated_namespace']
    assert data['server_sha256']==record['variants'][role]['sha256'] and data['client_sha256']==record['client']['sha256']
    assert data['server_exit_code']==data['client_exit_code']==0
    m=data['healthy']['healthy'];events={e['event']:e for e in data['events']};phase=data['healthy']['elapsed_seconds']
    row.update(healthy=m['per_second'],healthy_p99_ms=m['p99_upper_ms'],healthy_max_ms=m['max_ms'],cpu_wall=data['server_cpu_seconds']/phase,rss_ready_mib=events['ready']['process']['VmRSS']/1024,rss_dripped_mib=events['dripped']['process']['VmRSS']/1024,management_max_ms=max(x['latency_ms'] for x in data['management']),setup_seconds=events['ready']['seconds'],drip_seconds=events['dripped']['seconds']-events['ready']['seconds'],expiry_first=data['expiry_seconds']['first'],expiry_last=data['expiry_seconds']['last'],phase_seconds=phase)
   record['cases'].append(row);output.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(row),flush=True)
record['medians']={}
for workers,n,kind in cohorts:
 cohort=f'w{workers}-n{n}-{kind}'
 for role in servers:
  rows=[r for r in record['cases'] if r['cohort']==cohort and r['kind']==role];good=[r for r in rows if r['passed']];summary={'passed_runs':len(good),'failed_runs':len(rows)-len(good)}
  if good:
   fields=['healthy','healthy_p99_ms','healthy_max_ms','cpu_wall','rss_ready_mib','rss_dripped_mib','management_max_ms','setup_seconds','drip_seconds','phase_seconds']
   summary.update({k:statistics.median(r[k] for r in good) for k in fields});summary['ranges']={k:[min(r[k] for r in good),max(r[k] for r in good)] for k in fields}
  record['medians'][cohort+'/'+role]=summary
record['passed']=len(record['cases'])==48 and all(r['passed'] for r in record['cases']);output.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'passed':record['passed'],'cases':len(record['cases'])}),flush=True)
assert record['passed']
for name in ['routing-guard','burst-guard']:subprocess.run([sys.executable,str(root/f'artifacts/handshake-inline-{name}.py')],cwd=root,check=True)
